package com.coraline.feast;
import com.coraline.otherworld.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.core.BlockPos;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import java.nio.file.Path;
import java.util.List;

/** Opt-in automated client playthrough: real attack input, real falling/steering, journal, both key outcomes. */
@Mod.EventBusSubscriber(modid="coraline",value=Dist.CLIENT)
public final class ExpeditionVisualCheck {
    private static volatile int phase;private static int ticks;private static VisitData.Scene s;private static BlockPos c;private static volatile Vec3 oreTarget;private static volatile List<FortressActivity.Gate> gates;
    @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(!Boolean.getBoolean("coraline.expeditionVisualCheck")||e.phase!=TickEvent.Phase.START)return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;mc.options.pauseOnLostFocus=false;mc.options.renderDistance().set(10);ticks++;
        if(phase==0){phase=1;mc.getSingleplayerServer().execute(()->setup(mc.getSingleplayerServer()));return;}
        if(phase==2){if(ticks%100==0){capture(mc,"mineshaft_entry.png");phase=3;mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);s.loop.expedition.putLong("VoiceUntil",OtherMotherLoop.now(p));ExpeditionActivities.tick(p,s,c);var ore=MineshaftActivity.generate(s.loop.expedition.getLong("Seed")).ores().get(0);var at=c.offset(ore.offset());var room=MineshaftActivity.generate(s.loop.expedition.getLong("Seed")).rooms().get(0);var stand=new Vec3(c.getX()+room.x()+.5,c.getY()+room.y(),at.getZ()+.5);stand=stand.add(Math.signum(at.getX()-stand.x)*6,0,0);ActivityScenery.teleport(p,stand);oreTarget=Vec3.atCenterOf(at);phase=4;});}}
        if(phase==4){look(mc,oreTarget);mc.options.keyAttack.setDown(true);if(ticks%80==0){capture(mc,"mineshaft_mining.png");mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);if(s.loop.expedition.getInt("Count")<1)throw new IllegalStateException("Real mining input did not collect ore");var cart=p.serverLevel().getEntitiesOfClass(net.minecraft.world.entity.vehicle.Minecart.class,ExpeditionActivities.bounds(c,s.loop.activity)).stream().findFirst().orElseThrow();ActivityScenery.teleport(p,cart.position().add(-1.3,0,0));MineshaftActivity.cart(p,cart);phase=40;});}}
        if(phase==40){mc.options.keyAttack.setDown(false);mc.player.setYRot(180);mc.player.setXRot(5);if(ticks%80==0)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);if(p.getVehicle()==null){if(p.getZ()>c.getZ()-70)throw new IllegalStateException("Cart did not reach the lower station");com.mojang.logging.LogUtils.getLogger().info("EXPEDITION rail shortcut reached lower station at "+p.position());MineshaftActivity.finish(p,s,true);phase=5;}});}
        if(phase==5){mc.options.keyAttack.setDown(false);phase=6;mc.getSingleplayerServer().execute(()->{enter(mc.getSingleplayerServer(),OtherMotherActivities.Activity.OTHER_NETHER_FORTRESS);var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);s.loop.expedition.putLong("VoiceUntil",OtherMotherLoop.now(p));ExpeditionActivities.tick(p,s,c);gates=FortressActivity.generate(s.loop.expedition.getLong("Seed"));phase=7;});}
        if(phase==7){mc.player.setYRot(180);mc.player.setXRot(75);int pass=s.loop.expedition.getInt("Passed");var target=pass<7?new Vec3(c.getX()+gates.get(pass).x()+.5,0,c.getZ()+gates.get(pass).z()+.5):new Vec3(c.getX()+.5,0,c.getZ()+.5);double dx=target.x-mc.player.getX(),dz=target.z-mc.player.getZ();mc.options.keyLeft.setDown(dx<-.3);mc.options.keyRight.setDown(dx>.3);mc.options.keyUp.setDown(dz<-.3);mc.options.keyDown.setDown(dz>.3);
            if(ticks%100==0){capture(mc,"fortress_descent_"+pass+".png");mc.getSingleplayerServer().execute(()->{int state=s.loop.expedition.getInt("Phase");if(state==5){com.mojang.logging.LogUtils.getLogger().info("EXPEDITION QA FAILED: "+s.loop.expedition);phase=16;return;}if(state==3){var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);long length=OtherMotherLoop.now(p)-s.loop.expedition.getLong("DropAt");com.mojang.logging.LogUtils.getLogger().info("EXPEDITION drop completed in "+length+" ticks");phase=8;}});}}
        if(phase==8){movementOff(mc);mc.player.setYRot(180);mc.player.setXRot(0);capture(mc,"fortress_vault.png");phase=9;mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);var prize=LoopProps.nearby(p.serverLevel(),s,c.offset(28,-277,-5)).stream().filter(a->a.slot==740).findFirst().orElseThrow();FortressActivity.interactProp(p,s,prize);enter(mc.getSingleplayerServer(),OtherMotherActivities.Activity.OTHER_WOODLAND_MANSION);s.loop.expedition.putLong("VoiceUntil",OtherMotherLoop.now(p));ExpeditionActivities.tick(p,s,c);phase=10;});}
        if(phase==10&&ticks%100==0){capture(mc,"mansion_gallery.png");phase=11;mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);for(int i=0;i<6;i++)MansionActivity.discover(p,s,i);phase=12;});}
        if(phase==12&&ticks%100==0){capture(mc,"mansion_journal.png");mc.setScreen(null);phase=13;mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);var game=MansionActivity.puzzle(s);if(!MansionActivity.choose(p,s,game.jackpot()))throw new IllegalStateException("Mansion key did not work");var r=game.rooms().get(game.jackpot());ActivityScenery.teleport(p,Vec3.atBottomCenterOf(MansionActivity.door(c,r).offset(MansionActivity.side(r)*5,0,2)));p.connection.teleport(p.getX(),p.getY(),p.getZ(),180,0);phase=14;});}
        if(phase==14&&ticks%100==0){capture(mc,"mansion_vault.png");phase=15;mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);var prop=p.serverLevel().getEntitiesOfClass(ScenePropEntity.class,ExpeditionActivities.bounds(c,s.loop.activity),a->a.slot==750).stream().findFirst().orElseThrow();MansionActivity.interactProp(p,s,prop);if(!ActivityWorld.exitReady(s))throw new IllegalStateException("Mansion exit missing");com.mojang.logging.LogUtils.getLogger().info("CORALINE_EXPEDITION_CLIENT_CHECK PASSED");phase=16;});}
        if(phase==16){movementOff(mc);mc.stop();}
    }
    private static void movementOff(Minecraft mc){mc.options.keyAttack.setDown(false);mc.options.keyLeft.setDown(false);mc.options.keyRight.setDown(false);mc.options.keyUp.setDown(false);mc.options.keyDown.setDown(false);}
    private static void look(Minecraft mc,Vec3 at){if(at==null)return;var v=at.subtract(mc.player.getEyePosition());mc.player.setYRot((float)Math.toDegrees(Math.atan2(-v.x,v.z)));mc.player.setXRot((float)-Math.toDegrees(Math.atan2(v.y,Math.sqrt(v.x*v.x+v.z*v.z))));}
    private static void capture(Minecraft mc,String name){try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(Path.of("../artwork/"+name));}catch(Exception ex){throw new RuntimeException(ex);}}
    private static void setup(MinecraftServer server){var p=server.getPlayerList().getPlayers().get(0);p.setGameMode(GameType.CREATIVE);var door=new DoorData.Door();door.owner=p.getUUID();door.pos=new BlockPos(59000,80,59000);DoorData.get(server).doors.put(door.id,door);var realm=RealmData.get(server).realm(door);realm.ready=true;realm.parentGeneration=1;realm.porch=realm.doorPos;var other=server.getLevel(OtherWorld.KEY);for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)other.setBlock(realm.doorPos.offset(x,-1,z),Blocks.CHERRY_PLANKS.defaultBlockState(),2);
        s=new VisitData.Scene();s.owner=p.getUUID();s.door=door.id;s.stage=VisitData.Stage.DONE;s.table=realm.doorPos;s.piano=realm.doorPos;s.loop.portal=realm.doorPos;s.loop.generation=1;s.loop.phase=OtherMotherLoopState.Phase.READY;s.loop.activity=OtherMotherActivities.Activity.OTHER_MINESHAFT;VisitData.get(server).scenes.put(p.getUUID(),s);p.getPersistentData().putUUID("CoralineVisitDoor",door.id);p.teleportTo(other,realm.doorPos.getX()+.5,80,realm.doorPos.getZ()+.5,0,0);ActivityWorld.enter(p,s);c=ExpeditionActivities.center(p,s);phase=2;
    }
    private static void enter(MinecraftServer server,OtherMotherActivities.Activity activity){var p=server.getPlayerList().getPlayers().get(0);ActivityWorld.exit(p,s);s.loop.phase=OtherMotherLoopState.Phase.READY;s.loop.activity=activity;s.loop.generation++;ActivityWorld.enter(p,s);c=ExpeditionActivities.center(p,s);}
}
